use parking_lot::Mutex;
use std::sync::Arc;
use watcher::WatcherHub;
use workspace::WorkspaceRegistry;

pub struct AppState {
    pub workspaces: Arc<Mutex<WorkspaceRegistry>>,
    pub watcher: Arc<WatcherHub>,
    pub metadata_engine: Arc<Mutex<Option<md_studio_core::index::ReindexEngine>>>,
    pub launch_path: Arc<Mutex<Option<String>>>,
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let launch_path = md_studio_core::first_existing_markdown_path(std::env::args().skip(1))
        .map(|p| p.to_string_lossy().into_owned());

    let launch_path_state = Arc::new(Mutex::new(launch_path));

    let state = AppState {
        workspaces: Arc::new(Mutex::new(WorkspaceRegistry::default())),
        watcher: Arc::new(WatcherHub::default()),
        metadata_engine: Arc::new(Mutex::new(None)),
        launch_path: launch_path_state.clone(),
    };

    tauri::Builder::default()
        .plugin(tauri_plugin_single_instance::init(|app, args, _cwd| {
            use tauri::{Emitter, Manager};
            if let Some(path) = md_studio_core::first_existing_markdown_path(args.iter().skip(1)) {
                let path_str = path.to_string_lossy().into_owned();
                let _ = app.emit("app://open-file", serde_json::json!({ "path": path_str }));
            }
            if let Some(splash) = app.get_webview_window("splashscreen") {
                let _ = splash.close();
            }
            if let Some(w) = app.get_webview_window("main") {
                let _ = w.unminimize();
                let _ = w.show();
                let _ = w.set_focus();
            }
        }))
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())
        .manage(state)
        .setup(|app| {
            use tauri::Manager;
            let handle = app.handle().clone();
            std::thread::spawn(move || {
                std::thread::sleep(std::time::Duration::from_secs(6));
                if let Some(splash) = handle.get_webview_window("splashscreen") {
                    let _ = splash.close();
                }
                if let Some(main) = handle.get_webview_window("main") {
                    let _ = main.show();
                    let _ = main.set_focus();
                }
            });
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            commands::open_workspace,
            commands::list_entries,
            commands::read_document,
            commands::save_document,
            commands::search_workspace,
            commands::export_html,
            commands::get_launch_path,
            commands::metadata::get_workspace_stats,
            commands::metadata::get_document_metadata,
            commands::metadata::get_all_documents,
            commands::metadata::trigger_reindex,
            commands::metadata::get_wiki_links_for,
            commands::metadata::resolve_wiki_link,
            commands::metadata::get_resolved_wiki_links_for,
            commands::metadata::get_tags,
            commands::metadata::get_backlinks,
            commands::close_splash,
            watcher::start_watching,
            watcher::stop_watching,
        ])
        .run(tauri::generate_context!())
        .expect("error while running MD Studio");
}

export interface DocumentMetadata {
  path: string;
  title: string | null;
  headings: Heading[];
  links: Link[];
  wikiLinks: WikiLink[];
  tags: string[];
  images: string[];
  tables: number;
  mermaidBlocks: number;
  katexBlocks: number;
  wordCount: number;
  lineCount: number;
  lastModified: number;
}

export interface Heading {
  depth: number;
  text: string;
  anchor: string;
}

export interface Link {
  text: string;
  url: string;
  isInternal: boolean;
  line: number;
}

export interface WikiLink {
  target: string;
  alias: string | null;
  line: number;
}

export type WikiLinkStatus = "resolved" | "unresolved" | "ambiguous";

export interface ResolvedWikiLink extends WikiLink {
  status: WikiLinkStatus;
  path: string | null;
  candidates: string[];
}

export interface WorkspaceStats {
  totalDocuments: number;
  totalWords: number;
  totalLinks: number;
  totalWikiLinks: number;
  totalTags: number;
  uniqueTags: number;
  totalMermaid: number;
  totalKatex: number;
}

export interface ReindexReport {
  indexed: number;
  skipped: number;
  errors: string[];
}

export interface BacklinkOccurrence {
  sourcePath: string;
  line: number;
  context: string | null;
}

export interface BacklinkGroup {
  sourcePath: string;
  sourceTitle: string | null;
  occurrences: BacklinkOccurrence[];
}

export interface BacklinkResult {
  targetPath: string;
  documentCount: number;
  occurrenceCount: number;
  groups: BacklinkGroup[];
}

import { invoke } from "@tauri-apps/api/core";
import type {
  DocumentMetadata,
  WorkspaceStats,
  WikiLink,
  ResolvedWikiLink,
  ReindexReport,
  BacklinkResult,
} from "../../types/metadata";

export const emptyBacklinks = (path = ""): BacklinkResult => ({
  targetPath: path,
  documentCount: 0,
  occurrenceCount: 0,
  groups: [],
});

const isTauri = () => typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;

export const getWorkspaceStats = async (): Promise<WorkspaceStats> => {
  if (!isTauri()) {
    return {
      totalDocuments: 0,
      totalWords: 0,
      totalLinks: 0,
      totalWikiLinks: 0,
      totalTags: 0,
      uniqueTags: 0,
      totalMermaid: 0,
      totalKatex: 0,
    };
  }
  return invoke("get_workspace_stats");
};

export const getDocumentMetadata = async (path: string): Promise<DocumentMetadata | null> => {
  if (!isTauri()) return null;
  return invoke("get_document_metadata", { path });
};

export const getAllDocuments = async (): Promise<DocumentMetadata[]> => {
  if (!isTauri()) return [];
  return invoke("get_all_documents");
};

export const triggerReindex = async (): Promise<ReindexReport> => {
  if (!isTauri()) {
    return { indexed: 0, skipped: 0, errors: [] };
  }
  return invoke("trigger_reindex");
};

export const getWikiLinksFor = async (path: string): Promise<WikiLink[]> => {
  if (!isTauri()) return [];
  return invoke("get_wiki_links_for", { path });
};

export const resolveWikiLink = async (target: string): Promise<ResolvedWikiLink> => {
  if (!isTauri()) {
    return { target, alias: null, line: 0, status: "unresolved", path: null, candidates: [] };
  }
  return invoke("resolve_wiki_link", { target });
};

export const getResolvedWikiLinksFor = async (path: string): Promise<ResolvedWikiLink[]> => {
  if (!isTauri()) return [];
  return invoke("get_resolved_wiki_links_for", { path });
};

export const getTags = async (): Promise<string[]> => {
  if (!isTauri()) return [];
  return invoke("get_tags");
};

export const getBacklinks = async (path: string): Promise<BacklinkResult> => {
  if (!isTauri()) return emptyBacklinks(path);
  return invoke("get_backlinks", { path });
};

import { useState, useEffect, useCallback } from "react";
import type {
  DocumentMetadata,
  WorkspaceStats,
  WikiLink,
  ResolvedWikiLink,
  ReindexReport,
  BacklinkResult,
} from "../types/metadata";
import * as metadataIpc from "../lib/ipc/metadata";

export function useMetadata(currentPath?: string) {
  const [stats, setStats] = useState<WorkspaceStats | null>(null);
  const [currentDocMetadata, setCurrentDocMetadata] = useState<DocumentMetadata | null>(null);
  const [allDocs, setAllDocs] = useState<DocumentMetadata[]>([]);
  const [tags, setTags] = useState<string[]>([]);
  const [wikiLinks, setWikiLinks] = useState<WikiLink[]>([]);
  const [resolvedWikiLinks, setResolvedWikiLinks] = useState<ResolvedWikiLink[]>([]);
  const [backlinks, setBacklinks] = useState<BacklinkResult>(metadataIpc.emptyBacklinks());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const refreshStats = useCallback(async () => {
    try {
      const s = await metadataIpc.getWorkspaceStats();
      setStats(s);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, []);

  const refreshTags = useCallback(async () => {
    try {
      const t = await metadataIpc.getTags();
      setTags(t);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, []);

  const refreshAllDocs = useCallback(async () => {
    try {
      const docs = await metadataIpc.getAllDocuments();
      setAllDocs(docs);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, []);

  const refreshCurrentDoc = useCallback(async (path: string) => {
    try {
      const meta = await metadataIpc.getDocumentMetadata(path);
      setCurrentDocMetadata(meta);
      const links = await metadataIpc.getWikiLinksFor(path);
      setWikiLinks(links);
      const resolvedLinks = await metadataIpc.getResolvedWikiLinksFor(path);
      setResolvedWikiLinks(resolvedLinks);
      const incoming = await metadataIpc.getBacklinks(path);
      setBacklinks(incoming);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, []);

  const reindex = useCallback(async (): Promise<ReindexReport | null> => {
    setLoading(true);
    setError(null);
    try {
      const report = await metadataIpc.triggerReindex();
      await refreshStats();
      await refreshTags();
      await refreshAllDocs();
      if (currentPath) {
        await refreshCurrentDoc(currentPath);
      }
      return report;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      setError(msg);
      return null;
    } finally {
      setLoading(false);
    }
  }, [currentPath, refreshStats, refreshTags, refreshAllDocs, refreshCurrentDoc]);

  useEffect(() => {
    void refreshStats();
    void refreshTags();
    void refreshAllDocs();
  }, [refreshStats, refreshTags, refreshAllDocs]);

  useEffect(() => {
    if (currentPath) {
      void refreshCurrentDoc(currentPath);
    } else {
      setCurrentDocMetadata(null);
      setWikiLinks([]);
      setResolvedWikiLinks([]);
      setBacklinks(metadataIpc.emptyBacklinks());
    }
  }, [currentPath, refreshCurrentDoc]);

  return {
    stats,
    currentDocMetadata,
    allDocs,
    tags,
    wikiLinks,
    resolvedWikiLinks,
    backlinks,
    loading,
    error,
    refreshStats,
    refreshTags,
    refreshAllDocs,
    reindex,
  };
}
